import Shared
import SwiftUI

/// « Licences open source »: the components of the iOS app, grouped by license, each with its full text. Same
/// content as Android's `LicensesScreen` (`OpenSourceNotices`, generated by design/licenses/notices.py).
struct LicensesView: View {
    @Environment(\.dismiss) private var dismiss

    private let groups = OpenSourceNotices.shared.groupsFor(platform: .ios)

    var body: some View {
        AboutScaffold(title: Text("Licences open source"), onBack: { dismiss() }) {
            Text("Ocimio utilise ces composants open source. Merci à leurs auteurs.")
                .textStyle(.bodyCompact)
                .foregroundStyle(Palette.inkSoft)
            ForEach(groups, id: \.license.id) { group in
                LicenseBlock(group: group)
            }
        }
    }
}

private struct LicenseBlock: View {
    let group: LicenseGroup

    @State private var expanded = false

    var body: some View {
        BlockSection(title: Text(verbatim: group.license.title)) {
            VStack(alignment: .leading, spacing: 0) {
                ForEach(group.components, id: \.name) { component in
                    VStack(alignment: .leading, spacing: 2) {
                        Text(verbatim: component.name)
                            .textStyle(.listRow)
                            .foregroundStyle(Palette.ink)
                        Text(verbatim: component.owner)
                            .textStyle(.help)
                            .foregroundStyle(Palette.inkSoft)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding(.horizontal, 16)
                    .padding(.vertical, 10)
                    BlockDivider()
                }
                Button {
                    withAnimation(.easeInOut(duration: 0.25)) { expanded.toggle() }
                } label: {
                    Text(expanded ? "Masquer la licence" : "Lire la licence")
                        .textStyle(.textButton)
                        .foregroundStyle(Palette.basil)
                        .frame(maxWidth: .infinity, minHeight: 48, alignment: .leading)
                        .padding(.horizontal, 16)
                        .contentShape(.rect)
                }
                .buttonStyle(.plain)
                if expanded {
                    BlockDivider()
                    Text(verbatim: group.license.text)
                        .textStyle(.caption)
                        .foregroundStyle(Palette.ink)
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .padding(16)
                }
            }
            .blockStyle()
        }
    }
}
